+.toast { position: fixed; bottom: 90px; left: calc(50% + var(--side-w)/2); transform: translate(-50%, 150%); background: var(--ink); color: #fff; font-family: var(--mono); font-size: 12px; letter-spacing: .04em; padding: 13px 20px; border-radius: 11px; z-index: 2200; display: flex; align-items: center; gap: 10px; box-shadow: 0 12px 32px rgba(0,0,0,.3); transition: transform .45s var(--ease); pointer-events: none; }
+.toast.show { transform: translate(-50%,0); pointer-events: auto; }
